     1	// Station jump-in (13 §6, rule `facility.enter`): the station arrives near the planets it serves,
     2	// ponderously, summoned by the captain whose attachment first brings it into the round. The summoner
     3	// flies ahead to where it will come in (a guest jumps in there), so the eye is waiting at the spot
     4	// (2026-10-12); then space folds and the station slides out, and a slow bloom spreads as it settles.
     5	// The beacon pulses, bearing and planet rings are retired (27 E1: the flight already says it). The
     6	// station's arrival is hero energy at rest (13 §6.1, 2026-10-13).
     7	import { RULE } from '@shared/engine/pace';
     8	import { HERO, HERO_GLOW } from '../../../chart/art/energy';
     9	import { cmd, crewHoldMs, drawnR, one, phaseMs, pointOf, present, repeats } from '../../../chart/fx/commands';
    10	import type { CommandCall, ManeuverDef } from '../../../chart/fx/types';
    11	import { themeCmd } from '../commands';
    12	
    13	export const stationJumpIn: ManeuverDef = {
    14	  id: RULE.facilityEnter,
    15	  title: 'Station jump-in',
    16	  phase: {
    17	    tell: (c) => {
    18	      const f = one(c, 'facility') ?? one(c, 'subject');
    19	      return f ? [cmd.ring({ at: f.at, r: drawnR(f) * 2.4, r1: drawnR(f) * 0.6, color: HERO, durS: 0.3, alpha: 0.35 })] : [];
    20	    },
    21	    gather: (c, m) => {
    22	      const f = one(c, 'facility') ?? one(c, 'subject');
    23	      if (!f) return [];
    24	      const gather = phaseMs(m, 'gather');
    25	      const fly = gather; // the flight alone (27 E1: no beacon pulses)
    26	      const rest = crewHoldMs(m); // through the arrival, then a second with the summoner named (22 B9)
    27	      const R = drawnR(f);
    28	      const p = pointOf(f.at) ?? [f.node.world.x, f.node.world.y];
    29	      // The spot beside where it comes in, on the side the summoner arrives from (or toward the star).
    30	      const a = present(c, 'agent')[0];
    31	      const from = (a && pointOf(a.at)) ?? [0, 0];
    32	      const l = Math.hypot(from[0] - p[0], from[1] - p[1]) || 1;
    33	      const spot: [number, number] = [p[0] + ((from[0] - p[0]) / l) * R * 1.9, p[1] + ((from[1] - p[1]) / l) * R * 1.9];
    34	      const calls: CommandCall[] = [];
    35	      if (a) calls.push(cmd.pursue({ pk: a.node.projectionKey, durS: fly / 1000, holdS: rest / 1000, backS: 0.8, to: spot, look: f.at, wake: 4 }));
    36	      else {
    37	        const away = c.away?.agent?.[0];
    38	        if (away) calls.push(themeCmd.guest({ key: away.key, seed: away.seed, at: spot, face: p[0] >= spot[0] ? 1 : -1, durS: (gather + rest + 600) / 1000 }));
    39	      }
    40	      // Space folds as the flight ends (the flight is the call; this ring only repeats it).
    41	      calls.push(repeats(cmd.ring({ at: f.at, r: R * 2.2, r1: R * 0.8, color: HERO, durS: 0.6, alpha: 0.5 }, gather - 600)));
    42	      return calls;
    43	    },
    44	    act: (c) => {
    45	      const f = one(c, 'facility') ?? one(c, 'subject');
    46	      if (!f) return [];
    47	      const r = drawnR(f);
    48	      return [
    49	        cmd.act(f.key, 'jump'),
    50	        cmd.flare({ at: f.at, r, color: HERO_GLOW, scale: 1.3, linger: 2 }),
    51	        cmd.ring({ at: f.at, r: r * 0.7, r1: r * 1.6, color: HERO_GLOW, durS: 1.2, alpha: 0.7 }),
    52	      ];
    53	    },
    54	    land: (c) => {
    55	      const f = one(c, 'facility') ?? one(c, 'subject');
    56	      if (!f) return [];
    57	      return [repeats(cmd.ring({ at: f.at, r: drawnR(f), r1: drawnR(f) * 1.2, color: HERO_GLOW, durS: 0.6, alpha: 0.5 }))];
    58	    },
    59	  },
    60	};
