    else this.streak?.draw(p, p, 0, 0);
    const g = this.flash!.clear();
    if (u > 0.75) {
      const f = (u - 0.75) / 0.25;
      g.circle(slot[0], slot[1], (8 + 10 * f) * px).stroke({ width: 1.2 * px, color: 0xe8fbff, alpha: 0.5 * (1 - f) });
