export function passTangent(a: Pt, spot: Pt, home: Pt): [number, number] {
  const d1 = unit([spot[0] - a[0], spot[1] - a[1]]);
  const d2 = unit([home[0] - spot[0], home[1] - spot[1]]);
  const sum: [number, number] = [d1[0] + d2[0], d1[1] + d2[1]];
  if (Math.hypot(sum[0], sum[1]) < 1e-3) return [-d1[1], d1[0]];
  return unit(sum);
