export function volleyPhases(ps: readonly PhaseSpan[], turns: readonly VolleyTurn[]): readonly PhaseSpan[] {
  const echo = ps.find((p) => p.phase === 'echo');
  const restAt = ps.find((p) => p.phase === 'disperse')?.atMs ?? spanMs(ps);
